feedbackvariables.text:
/* 1. FONCTIONS UTILITAIRES */
sort_nuclei1(lst) := sort(lst, lambda([x,y], is(x[2] < y[2]) or (x[2]=y[2] and x[3] < y[3])));

get_particle_latex1(p) := block(
   [c, a, z, s, coeff_str, s_clean],
   c : p[1], a : p[2], z : p[3], s : p[4],
   if c = 1 then coeff_str : "" else coeff_str : sconcat(c),
   if s = "He" and a = 4 and z = 2 then return(sconcat("\(", coeff_str, "\\alpha", "\)")),
   if s = "e" and a = 0 and z = -1 then return(sconcat("\(", coeff_str, "\\beta^{-}", "\)")),
   if s = "e" and a = 0 and z = 1  then return(sconcat("\(", coeff_str, "\\beta^{+}", "\)")),
   if s = "\\gamma" then return(sconcat("\(", coeff_str, "\\gamma", "\)")),
   if s = "n" then return(sconcat("\(", coeff_str, "n", "\)")),
   if s = "p" then return(sconcat("\(", coeff_str, "p", "\)")),
   if search("*", s) > 0 then (
       s_clean : substring(s, 1, slength(s)),
       if c = 1 then return(sconcat("\({}^{", a, "}_{", z, "}", s_clean, "^*", "\)"))
       else return(sconcat("\(", c, " {}^{", a, "}_{", z, "}", s_clean, "^*", "\)"))
   ),
   if c = 1 then sconcat("\({}^{", a, "}_{", z, "}", s, "\)")
   else sconcat("\(", c, " {}^{", a, "}_{", z, "}", s, "\)")
);

get_coeffs_errors1(s_raw, t_raw) := block(
   [s_sorted, t_sorted, errors, i, p_latex],
   s_sorted : sort_nuclei1(s_raw),
   t_sorted : sort_nuclei1(t_raw),
   errors : [],
   if length(s_sorted) # length(t_sorted) then (
      return(["Attention : Le nombre de termes est incorrect (ex: 2n et non n+n)."])
   ),
   for i:1 thru length(s_sorted) do (
      if s_sorted[i][1] # t_sorted[i][1] then (
         p_latex : get_particle_latex1(t_sorted[i]),
         errors : endcons(
           sconcat("Pour \( ", p_latex, " \) : coeff ", s_sorted[i][1], " au lieu de ", t_sorted[i][1]),
           errors
         )
      )
   ),
   errors
);

/* 2. PRÉPARATION DES DONNÉES */
tmp_r1: if listp(ans1r) then ans1r else [];
tmp_p1: if listp(ans1p) then ans1p else [];

list_reactants_student1: map(get_particle_latex1, tmp_r1);
list_reactants_teacher1: map(get_particle_latex1, nuc1_rea);
list_products_student1:  map(get_particle_latex1, tmp_p1);
list_products_teacher1:  map(get_particle_latex1, nuc1_pro);

list_errors_coeffs_reactants1: get_coeffs_errors1(tmp_r1, nuc1_rea);
list_errors_coeffs_products1:  get_coeffs_errors1(tmp_p1, nuc1_pro);

/* 3. FEEDBACKS */
if list_reactants_student1 = [] then list_reactants_student1: ["(vide)"];
if list_reactants_teacher1 = [] then list_reactants_teacher1: ["(vide)"];
fb_error_reactants1: sconcat(
   "<div style='padding:15px;background:#fff5f5;border-radius:8px;border-left:5px solid #e74c3c;'>",
   "<h4 style='margin-top:0;color:#c0392b;'>❌ Les réactifs sont incorrects</h4>",
   "<strong style='color:#d9534f;'>Votre réponse :</strong>",
   "<ul style='color:#333;margin-top:5px;'><li>", simplode(list_reactants_student1, "</li><li>"), "</li></ul>",
   "<strong style='color:#555;'>Réponse attendue :</strong>",
   "<ul style='color:#333;margin-top:5px;'><li>", simplode(list_reactants_teacher1, "</li><li>"), "</li></ul>",
   "</div>"
);
if list_products_student1 = [] then list_products_student1: ["(vide)"];
if list_products_teacher1 = [] then list_products_teacher1: ["(vide)"];
fb_error_products1: sconcat(
   "<div style='padding:15px;background:#fff5f5;border-radius:8px;border-left:5px solid #e74c3c;'>",
   "<h4 style='margin-top:0;color:#c0392b;'>❌ Les produits sont incorrects</h4>",
   "<strong style='color:#d9534f;'>Votre réponse :</strong>",
   "<ul style='color:#333;margin-top:5px;'><li>", simplode(list_products_student1, "</li><li>"), "</li></ul>",
   "<strong style='color:#555;'>Réponse attendue :</strong>",
   "<ul style='color:#333;margin-top:5px;'><li>", simplode(list_products_teacher1, "</li><li>"), "</li></ul>",
   "</div>"
);
if list_errors_coeffs_reactants1 = [] then (
   fb_reactants_coeffs1: "<strong>Erreur inconnue.</strong>"
) else (
   fb_reactants_coeffs1: sconcat(
      "<div style='padding:15px;background:#fffbf0;border-radius:8px;border-left:5px solid #f39c12;'>",
      "<h4 style='margin-top:0;color:#d35400;'>⚠️ Attention aux coefficients (Réactifs)</h4>",
      "<span style='color:#e67e22;font-weight:bold;'>", simplode(list_errors_coeffs_reactants1, "<br/><br/>"), "</span>",
      "</div>"
   )
);
if list_errors_coeffs_products1 = [] then (
   fb_products_coeffs1: "<strong>Erreur inconnue.</strong>"
) else (
   fb_products_coeffs1: sconcat(
      "<div style='padding:15px;background:#fffbf0;border-radius:8px;border-left:5px solid #f39c12;'>",
      "<h4 style='margin-top:0;color:#d35400;'>⚠️ Attention aux coefficients (Produits)</h4>",
      "<span style='color:#e67e22;font-weight:bold;'>", simplode(list_errors_coeffs_products1, "<br/><br/>"), "</span>",
      "</div>"
   )
);
fb_success1: sconcat(
   "<div style='padding:15px;background:#f0fff4;border-radius:8px;border-left:5px solid #27ae60;'>",
   "<h4 style='margin-top:0;color:#27ae60;'>✅ Excellent !</h4>",
   "<span style='color:#2ecc71;'>La réaction est correctement équilibrée.</span>",
   "</div>"
);

/* 4. NETTOYAGE ET VÉRIFICATIONS */
clean_symbol1(s) := if search("*", s) > 0 then substring(s, 1, slength(s)) else s;
tmp_r_clean1: map(lambda([x], [x[1], x[2], x[3], clean_symbol1(x[4])]), tmp_r1);
tmp_p_clean1: map(lambda([x], [x[1], x[2], x[3], clean_symbol1(x[4])]), tmp_p1);
ta_r_clean1:  map(lambda([x], [x[1], x[2], x[3], clean_symbol1(x[4])]), nuc1_rea);
ta_p_clean1:  map(lambda([x], [x[1], x[2], x[3], clean_symbol1(x[4])]), nuc1_pro);

verif_especes1: if (setify(map(lambda([x], rest(x)), tmp_r_clean1)) = setify(map(lambda([x], rest(x)), ta_r_clean1))) and (setify(map(lambda([x], rest(x)), tmp_p_clean1)) = setify(map(lambda([x], rest(x)), ta_p_clean1))) then true else false;
verif_total1: if (setify(tmp_r_clean1) = setify(ta_r_clean1)) and (setify(tmp_p_clean1) = setify(ta_p_clean1)) then true else false;
verif_total_precise1: if (setify(tmp_r1) = setify(nuc1_rea)) and (setify(tmp_p1) = setify(nuc1_pro)) then true else false;
asterisk_missing1: if verif_total1 and not verif_total_precise1 then true else false;
fb_asterisk1: sconcat(
   "<div style='padding:15px;background:#fffbf0;border-radius:8px;border-left:5px solid #f39c12;'>",
   "<h4 style='margin-top:0;color:#d35400;'>⚠️ Attention aux états excités</h4>",
   "<span style='color:#e67e22;'>La structure est correcte, mais vérifiez les états excités (*).</span>",
   "</div>"
);
